@page "/apply"
@namespace sv_04d6c402fb3e4adeb73a619c8b6fb3fb.Components.Pages.Apply
@using sv_04d6c402fb3e4adeb73a619c8b6fb3fb.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="_currentStep" OnStepClicked="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep
                FullName="@_fullName"
                Email="@_email"
                Phone="@_phone"
                Address="@_address"
                ValidateEmail="ApplicationService.ValidateEmailAsync"
                OnNext="HandlePersonalInfoNext" />
            break;

        case 1:
            <WorkHistoryStep
                Entries="_workEntries"
                OnNext="HandleWorkHistoryNext"
                OnBack="GoBack" />
            break;

        case 2:
            <ReferencesStep
                References="_references"
                OnNext="HandleReferencesNext"
                OnBack="GoBack" />
            break;

        case 3:
            <CoverLetterStep
                CoverLetter="@_coverLetter"
                OnNext="HandleCoverLetterNext"
                OnBack="GoBack" />
            break;

        case 4:
            <ReviewStep
                FullName="@_fullName"
                Email="@_email"
                Phone="@_phone"
                Address="@_address"
                WorkEntries="_workEntries"
                References="_references"
                CoverLetter="@_coverLetter"
                IsSubmitted="_isSubmitted"
                ApplicationId="_applicationId"
                OnSubmit="HandleSubmit"
                OnBack="GoBack"
                OnEditStep="GoToStep" />
            break;
    }
</div>

@code {
    private int _currentStep;
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";
    private List<WorkHistoryStep.WorkEntryState> _workEntries = new();
    private List<ReferencesStep.ReferenceState> _references = new();
    private string _coverLetter = "";
    private bool _isSubmitted;
    private int? _applicationId;

    private void GoToStep(int step)
    {
        if (step < _currentStep)
            _currentStep = step;
    }

    private void GoBack()
    {
        if (_currentStep > 0)
            _currentStep--;
    }

    private void HandlePersonalInfoNext(PersonalInfoStep.PersonalInfoResult result)
    {
        _fullName = result.FullName;
        _email = result.Email;
        _phone = result.Phone;
        _address = result.Address;
        _currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkHistoryStep.WorkEntryState> entries)
    {
        _workEntries = entries;
        _currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceState> references)
    {
        _references = references;
        _currentStep = 3;
    }

    private void HandleCoverLetterNext(string coverLetter)
    {
        _coverLetter = coverLetter;
        _currentStep = 4;
    }

